/* Position the container to the far left by disabling certain styles. */
/* Style and size the container */
.cmp-wrapper {
	min-height: initial;
	flex-direction: initial;
	box-shadow: initial;
}

.cmp.bottom footer {
   margin-top: 0;
}

#uc-main-dialog {
	margin: 50px 24px 24px;
	max-width: 500px;
	max-height: 500px;
	border-top-left-radius: 16px;
	border-top-right-radius: 16px;
	border-bottom-left-radius: 16px;
	border-bottom-right-radius: 16px;
}

#uc-main-dialog.mobile {
	max-width: calc(100% - 48px);
}

/* Disable the flex to allow the buttons to align right */
.buttons-row button {
	flex: initial;
	width: auto;
	padding: 10px 24px;
	font-weight: normal;
}

footer.bottom {
	row-gap: 16px;
  flex-direction: column;
}

/* Add back the underline for the powered by link */
.poweredBy a {
	text-decoration: underline;
}

/* Add support for underlined Privacy Policy and More Information links */
a.uc-button-link {
	text-decoration: underline;
}

/* Styles for Mobile */
.mobile .buttons {
	display: flex;
	flex-direction: column;
	row-gap: 4px;
	width: 100%;
}

/* Save Settings Button */
#save {
	border: 1px solid #303030;
}







/* VERSION 2 CSS */

/* Position the container to the far left by disabling certain styles. */
/* [data-testid="uc-default-banner"],*/
.uc-layer {
	min-height: initial;
	flex-direction: initial; 
	box-shadow: initial;
}

/* Style and size the container */
/* [data-testid="uc-banner-content"],*/
.uc-banner-content {
    margin: 50px 24px 24px;
    max-width: 425px;
    max-height: 500px;
    border-top-left-radius: 16px;
    border-top-right-radius: 16px;
    border-bottom-left-radius: 16px;
    border-bottom-right-radius: 16px;
  }

/* Disable the flex to allow the buttons to align right */
/* [data-testid="uc-buttons-container"] button, */
.uc-action-button {
	flex: initial;
	width: auto;
	padding: 10px 24px;
	font-weight: normal;
}

/* Add back the underline for the powered by link */
/* [data-testid="uc-footer"] a,*/
.uc-powered-by a {
	text-decoration: underline; 
}

/* Add support for underlined Privacy Policy and More Information links */
/* [data-testid="uc-anchor-link"] */
.uc-links {
  text-decoration: underline;
}

/* Styles for Mobile */
/* UC Switches to the first-line-buttons on mobile. Add styling for that handler. */

/* Disable the flex to allow the buttons to align right */
/* [data-testid="first-line-buttons"], */
.uc-buttons-container__mobile {
	flex-direction: row;
	flex-wrap: wrap;
	column-gap: 16px; /* UNABLE TO STYLE VIA CUSTOM CSS */
	row-gap: 8px; /* UNABLE TO STYLE VIA CUSTOM CSS */
}

/* [data-testid="first-line-buttons"] button, */
.uc-action-button__mobile {
	display: inline-block;
	flex: initial;
	width: auto;
	padding: 10px 24px;
	font-weight: normal;
	flex: 1;
}

/* Save Settings Button */
.uc-save-button {
border: 1px solid #303030;
}
/* [data-testid="first-line-buttons"] button[data-testid="uc-save-button"], */
.uc-save-button__mobile {
	width: 100% !important;
	flex: initial;
} 

/* Safari Browser users only */
.uc-banner-content__mobileSmall {
width: auto;
margin: 16px;
}
.uc-banner-content__mobileExtraSmall {
width: auto;
margin: 16px;
}
